<script setup lang="ts">
import { Clipboard, RefreshCw } from '@lucide/vue'
import { ref } from 'vue'
import { applyUpdate } from '@/infrastructure/updater/offline-runtime'
import { decideUpdate, fetchReleaseManifest } from '@/infrastructure/updater/release-manifest'
import { ensureDeviceId } from '@/infrastructure/licensing/device-id'
import { humanizeReason, requestVerify } from '@/infrastructure/licensing/license-api'
import { copyText } from '@/infrastructure/platform/clipboard'
import { useAppStore } from '@/stores/app-store'
import wechatQr from '@/assets/wechat-qr.png'
import AppDialog from '@/components/AppDialog.vue'

const store = useAppStore()
const appVersion = import.meta.env.VITE_APP_VERSION ?? '1.0.5'
const nativeBuild = Number.parseInt(import.meta.env.VITE_NATIVE_BUILD ?? '4', 10)
// 一体化状态：检查中 + 下载中 共用一个 busy。检查到新版本后直接进入下载，下载成功会 reload（不再需要解绑）
const busy = ref(false)
const message = ref('平时不会检查或上传任何内容。只有点击下方按钮才联网检查更新。')
const confirmOpen = ref(false)

async function copyWechat(): Promise<void> {
  try {
    await copyText('zdx-lhl')
    message.value = '微信号已复制'
  } catch (cause) {
    message.value = cause instanceof Error ? cause.message : '复制失败'
  }
}

function askCheck(): void {
  if (!busy.value) confirmOpen.value = true
}

/**
 * 检查更新前顺带复查授权（阶段 5）：
 * - 授权有效 / 未激活 / 网络失败 → 放行（宽容处理，不阻断更新）
 * - 授权已被后端明确否定（作废/不在名单）→ 阻止本次更新，提示联系作者
 * 返回 null 表示放行，字符串表示阻止原因。
 */
async function verifyLicenseForUpdate(): Promise<string | null> {
  const settings = await store.repository.getSettings()
  // 未激活不拦截：检查更新是免费功能，授权拦截在记账功能层
  if (!settings.licenseCode) return null
  try {
    const deviceId = await ensureDeviceId(store.repository)
    const result = await requestVerify({ code: settings.licenseCode, deviceId })
    if (!result.ok) return `授权校验未通过：${humanizeReason(result.reason)}。如需继续更新，请联系作者。`
    return null
  } catch {
    // 网络失败：仅提示、不阻断更新（计划文档阶段 5 宽容处理）
    return null
  }
}

/**
 * 一体化更新流程：点「检查更新」→ 联网确认 → 授权复查 → 自动检查 → 如有新版本直接下载并安装 → 成功后 reload
 * - 已是最新版本：只更新 message，不下载
 * - 授权被否定：阻止更新，提示联系作者
 * - 检查/下载失败：catch 里写错误 message，busy 重置，按钮恢复可点
 * - 成功路径：applyUpdate 内部会 reload，函数不会自然返回（reload 带走页面）
 */
async function runCheckAndInstall(): Promise<void> {
  confirmOpen.value = false
  busy.value = true
  message.value = '正在检查…'
  try {
    // 1) 授权复查（作废码在此被拦）
    const blocked = await verifyLicenseForUpdate()
    if (blocked) {
      busy.value = false
      message.value = blocked
      return
    }
    // 2) 正常更新流程
    const manifest = await fetchReleaseManifest(import.meta.env.VITE_UPDATE_BASE_URL ?? '')
    const decision = decideUpdate(manifest, appVersion, nativeBuild)
    if (decision.kind === 'current') {
      busy.value = false
      message.value = '当前已是最新版本。'
      return
    }
    message.value = `发现新版本 ${manifest.productVersion}，正在下载并校验…`
    await applyUpdate(decision)
    // 成功后会 reload；只有 reload 失败或非网页版才走到这里
    busy.value = false
  } catch (error) {
    busy.value = false
    message.value = `${error instanceof Error ? error.message : '更新失败'}。当前版本和本地数据不受影响，可稍后再试。`
  }
}
</script>

<template>
  <main class="page update-page">
    <section class="card update-card">
      <span class="update-icon"><RefreshCw :size="34" aria-hidden="true" /></span>
      <h2>当前版本 {{ appVersion }}</h2>
      <p>{{ message }}</p>
      <button class="button primary" type="button" :disabled="busy" @click="askCheck">
        <RefreshCw :size="19" :class="{ spinning: busy }" />{{ busy ? '更新中…' : '检查更新' }}
      </button>
      <div class="safety-note">
        <span>仅点击检查后联网，不上传账单等本地数据。</span>
        <span>已激活用户会联网核验授权状态（仅授权码与设备标识）。</span>
        <span>检查或更新失败不会影响当前版本和本地数据。</span>
      </div>
    </section>
    <section class="card contact-card">
      <img :src="wechatQr" alt="联系作者的微信二维码" />
      <div>
        <h2>更新遇到问题？</h2>
        <p>扫码联系作者，备注“随手记用户”。</p>
        <button class="button secondary" type="button" @click="copyWechat"><Clipboard :size="18" />复制微信号</button>
      </div>
    </section>
  </main>

  <AppDialog :open="confirmOpen" title="检查更新需要联网" @close="confirmOpen = false">
    <p>检查更新需要连接网络，本次会联网获取最新版本信息。</p>
    <p>不会上传账单、备注等本地数据；已激活用户会联网核验授权状态（仅授权码与设备标识）。</p>
    <template #actions>
      <button class="button secondary" type="button" @click="confirmOpen = false">取消</button>
      <button class="button primary" type="button" :disabled="busy" @click="runCheckAndInstall">{{ busy ? '更新中…' : '继续' }}</button>
    </template>
  </AppDialog>
</template>

