import nacl from 'tweetnacl'
import { Capacitor, CapacitorHttp } from '@capacitor/core'
import { fromBase64Url } from '@/infrastructure/licensing/base64url'
import { UPDATE_PUBLIC_KEY } from './update-public-key'

export interface ReleaseArtifact {
  url: string
  sha256: string
  size: number
}

export interface ReleaseManifestPayload {
  schemaVersion: 1
  productVersion: string
  bundleVersion: string
  minimumNativeBuild: number
  dataSchemaVersion: number
  publishedAt: string
  releaseNotes: string[]
  webBundle?: ReleaseArtifact
  androidApk?: ReleaseArtifact
}

export interface SignedReleaseManifest extends ReleaseManifestPayload {
  signature: string
}

export type UpdateDecision =
  | { kind: 'current'; manifest: SignedReleaseManifest }
  | { kind: 'pwa'; manifest: SignedReleaseManifest }
  | { kind: 'bundle'; manifest: SignedReleaseManifest; artifact: ReleaseArtifact }
  | { kind: 'apk'; manifest: SignedReleaseManifest; artifact: ReleaseArtifact }

export function canonicalize(value: unknown): string {
  if (value === null || typeof value !== 'object') return JSON.stringify(value)
  if (Array.isArray(value)) return `[${value.map(canonicalize).join(',')}]`
  const record = value as Record<string, unknown>
  return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${canonicalize(record[key])}`).join(',')}}`
}

function unsignedPayload(manifest: SignedReleaseManifest): ReleaseManifestPayload {
  const { signature: _signature, ...payload } = manifest
  return payload
}

function assertArtifact(value: unknown, name: string): asserts value is ReleaseArtifact {
  const artifact = value as Partial<ReleaseArtifact>
  if (!artifact || typeof artifact !== 'object' || typeof artifact.url !== 'string' || !artifact.url) throw new Error(`${name}地址无效`)
  if (!/^[a-f\d]{64}$/i.test(artifact.sha256 ?? '')) throw new Error(`${name}校验值无效`)
  if (!Number.isSafeInteger(artifact.size) || Number(artifact.size) <= 0) throw new Error(`${name}文件大小无效`)
}

export function verifyReleaseManifest(value: unknown, publicKey = UPDATE_PUBLIC_KEY): SignedReleaseManifest {
  const manifest = value as Partial<SignedReleaseManifest>
  if (!manifest || typeof manifest !== 'object' || manifest.schemaVersion !== 1) throw new Error('更新清单版本不受支持')
  if (typeof manifest.productVersion !== 'string' || typeof manifest.bundleVersion !== 'string') throw new Error('更新版本无效')
  if (!Number.isSafeInteger(manifest.minimumNativeBuild) || !Number.isSafeInteger(manifest.dataSchemaVersion)) throw new Error('更新兼容信息无效')
  if (typeof manifest.publishedAt !== 'string' || Number.isNaN(Date.parse(manifest.publishedAt))) throw new Error('更新发布时间无效')
  if (!Array.isArray(manifest.releaseNotes) || manifest.releaseNotes.some((item) => typeof item !== 'string')) throw new Error('更新说明无效')
  if (manifest.webBundle) assertArtifact(manifest.webBundle, '热更新包')
  if (manifest.androidApk) assertArtifact(manifest.androidApk, 'APK')
  if (typeof manifest.signature !== 'string') throw new Error('更新签名缺失')
  const signed = manifest as SignedReleaseManifest
  const valid = nacl.sign.detached.verify(
    new TextEncoder().encode(canonicalize(unsignedPayload(signed))),
    fromBase64Url(signed.signature),
    fromBase64Url(publicKey),
  )
  if (!valid) throw new Error('更新签名验证失败，已拒绝安装')
  return signed
}

function versionParts(version: string): number[] {
  return version.split('+')[0].split('.').map((part) => Number.parseInt(part, 10) || 0)
}

export function compareVersions(left: string, right: string): number {
  const a = versionParts(left)
  const b = versionParts(right)
  for (let index = 0; index < Math.max(a.length, b.length); index += 1) {
    if ((a[index] ?? 0) !== (b[index] ?? 0)) return (a[index] ?? 0) > (b[index] ?? 0) ? 1 : -1
  }
  return 0
}

export function decideUpdate(
  manifest: SignedReleaseManifest,
  currentVersion: string,
  nativeBuild: number,
  platform = Capacitor.getPlatform(),
): UpdateDecision {
  if (compareVersions(manifest.productVersion, currentVersion) <= 0) return { kind: 'current', manifest }
  if (platform === 'web') {
    // 在线 PWA：一律走 ServiceWorker 更新（file:// 本地打开无 ServiceWorker，提示不支持）
    if (typeof location !== 'undefined' && location.protocol === 'file:') throw new Error('本地打开的文件不支持在线更新，请联系作者获取新版')
    return { kind: 'pwa', manifest }
  }
  if (platform === 'android') {
    if (nativeBuild < manifest.minimumNativeBuild || !manifest.webBundle) {
      if (!manifest.androidApk) throw new Error('此版本需要更新完整 APK，但发布端未提供安装包')
      return { kind: 'apk', manifest, artifact: manifest.androidApk }
    }
    return { kind: 'bundle', manifest, artifact: manifest.webBundle }
  }
  throw new Error('当前平台不支持此更新方式')
}

export async function fetchReleaseManifest(baseUrl: string, fetcher?: typeof fetch, publicKey = UPDATE_PUBLIC_KEY): Promise<SignedReleaseManifest> {
  const normalized = baseUrl.trim().replace(/\/$/, '')
  if (Capacitor.isNativePlatform() && !fetcher) {
    if (!normalized) throw new Error('尚未配置更新服务器地址')
    const url = `${normalized}/release.json`
    const response = await CapacitorHttp.get({ url, headers: { Accept: 'application/json', 'Cache-Control': 'no-cache' }, connectTimeout: 15_000, readTimeout: 15_000 })
    if (response.status < 200 || response.status >= 300) throw new Error(`更新服务器返回 ${response.status}`)
    return verifyReleaseManifest(typeof response.data === 'string' ? JSON.parse(response.data) : response.data, publicKey)
  }
  // 网页版：GitHub Release 直链无 CORS 头（浏览器拦截），改走 GitHub API 查版本 + jsDelivr 取清单
  if (Capacitor.getPlatform() === 'web' && !fetcher) return fetchWebReleaseManifest(fetch, publicKey)
  if (!normalized) throw new Error('尚未配置更新服务器地址')
  const url = `${normalized}/release.json`
  const response = await (fetcher ?? fetch)(url, { cache: 'no-store', headers: { Accept: 'application/json' } })
  if (!response.ok) throw new Error(`更新服务器返回 ${response.status}`)
  return verifyReleaseManifest(await response.json(), publicKey)
}

// ---- 网页版更新通道（GitHub API + jsDelivr CDN） ----
//
// 实测结论（2026-08）：
// - github.com 的 Release 直链没有 Access-Control-Allow-Origin，浏览器 fetch 一律被拦
// - api.github.com 有 CORS 头，可实时查询最新版本（60 次/小时限流，检查更新足够）
// - cdn.jsdelivr.net 可代理 GitHub 仓库文件且带 CORS 头；按 tag 拉取，缓存友好
//
// 流程：GitHub API 拿最新 tag → jsDelivr 按 tag 下载 cdn/release.json（多域名兜底）→ 验签
const GITHUB_LATEST_API = 'https://api.github.com/repos/zhangdx91-lang/app-release/releases/latest'
const JSDELIVR_MIRRORS = [
  'https://cdn.jsdelivr.net/gh/zhangdx91-lang/app-release',
  'https://fastly.jsdelivr.net/gh/zhangdx91-lang/app-release',
  'https://gcore.jsdelivr.net/gh/zhangdx91-lang/app-release',
]

/** 网络请求超时（毫秒）：避免手机网络不佳时界面一直停在“检查中/正在更新” */
const WEB_FETCH_TIMEOUT_MS = 20_000

/** 带 AbortController 超时的 fetch：走传入的 fetcher（测试注入用），超时即中止 */
async function fetchJsonWithTimeout(fetcher: typeof fetch, url: string, accept: string, timeoutMs = WEB_FETCH_TIMEOUT_MS): Promise<Response> {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), timeoutMs)
  try {
    return await fetcher(url, { cache: 'no-store', headers: { Accept: accept }, signal: controller.signal })
  } finally {
    clearTimeout(timer)
  }
}

function describeWebError(error: unknown): Error {
  if (error instanceof DOMException && error.name === 'AbortError') return new Error('网络超时，请检查网络后重试')
  return error instanceof Error ? error : new Error('更新清单获取失败')
}

export async function fetchWebReleaseManifest(fetcher: typeof fetch, publicKey = UPDATE_PUBLIC_KEY): Promise<SignedReleaseManifest> {
  const metaResponse = await fetchJsonWithTimeout(fetcher, GITHUB_LATEST_API, 'application/vnd.github+json')
  if (!metaResponse.ok) throw new Error(`版本信息获取失败 (${metaResponse.status})`)
  const meta = await metaResponse.json() as { tag_name?: unknown }
  const tag = typeof meta.tag_name === 'string' ? meta.tag_name : ''
  if (!/^v?\d+\.\d+\.\d+$/.test(tag)) throw new Error('版本信息格式无效')
  let lastError: unknown
  for (const mirror of JSDELIVR_MIRRORS) {
    try {
      const response = await fetchJsonWithTimeout(fetcher, `${mirror}@${tag}/cdn/release.json`, 'application/json')
      if (!response.ok) throw new Error(`更新清单返回 ${response.status}`)
      return verifyReleaseManifest(await response.json(), publicKey)
    } catch (error) {
      lastError = error
    }
  }
  throw describeWebError(lastError)
}
